def priority_from_label(label):
    """'P1' (most urgent) to 'P5' -> 1 to 5. Anything else, or out of range, gives 3."""
    try:
        n = int(label[1:])
    except (ValueError, IndexError):
        return 3
    if n < 1 or n > 5:
        return 3
    return n

def median(values):
    """Median of a non-empty list of numbers."""
    s = sorted(values)
    n = len(s)
    if n % 2 == 0:
        return (s[n // 2 - 1] + s[n // 2]) / 2
    else:
        return s[n // 2]

